class CavaAssignmentStatus(str, Enum):
    PENDIENTE = "PENDIENTE"
    ACTIVA = "ACTIVA"
    CERRADA = "CERRADA"
    CANCELADA = "CANCELADA"


class MembershipRole(str, Enum):
    TITULAR = "TITULAR"
    COMPLEMENTARIO = "COMPLEMENTARIO"


@dataclass(frozen=True)
class PhysicalCavaIdentity:
    cava_id: str
    empresa_id: str
    unidad_negocio_id: str
    stable_code: str


@dataclass(frozen=True)
class CavaAssignment:
    assignment_id: str
    cava_id: str
    status: CavaAssignmentStatus
    valid_from: str
    valid_to: Optional[str] = None


@dataclass(frozen=True)
class CavaMembership:
    membership_id: str
    assignment_id: str
    canonical_client_id: str
    role: MembershipRole
    titular_membership_id: Optional[str] = None
    valid_from: Optional[str] = None
    valid_to: Optional[str] = None


def validate_physical_cava_identity(cava: PhysicalCavaIdentity) -> None:
    for field_name, value in (("cava_id", cava.cava_id), ("empresa_id", cava.empresa_id), ("unidad_negocio_id", cava.unidad_negocio_id), ("stable_code", cava.stable_code)):
        if not str(value or "").strip():
            raise ValueError(f"PhysicalCavaIdentity requiere {field_name}")


def validate_cava_assignment(assignment: CavaAssignment) -> None:
    for field_name, value in (("assignment_id", assignment.assignment_id), ("cava_id", assignment.cava_id), ("valid_from", assignment.valid_from)):
        if not str(value or "").strip():
            raise ValueError(f"CavaAssignment requiere {field_name}")
    if assignment.valid_to and assignment.valid_to < assignment.valid_from:
        raise ValueError("valid_to no puede ser anterior a valid_from")
    if assignment.status == CavaAssignmentStatus.ACTIVA and assignment.valid_to:
        raise ValueError("Una asignacion ACTIVA no debe tener valid_to cerrado")


def validate_cava_membership(membership: CavaMembership) -> None:
    for field_name, value in (("membership_id", membership.membership_id), ("assignment_id", membership.assignment_id), ("canonical_client_id", membership.canonical_client_id)):
        if not str(value or "").strip():
            raise ValueError(f"CavaMembership requiere {field_name}")
    if membership.valid_from and membership.valid_to and membership.valid_to < membership.valid_from:
        raise ValueError("valid_to no puede ser anterior a valid_from")
    if membership.role == MembershipRole.TITULAR:
        if membership.titular_membership_id not in (None, ""):
            raise ValueError("TITULAR no debe apuntar a otra membresia titular")
        return
    if membership.role == MembershipRole.COMPLEMENTARIO:
        if not str(membership.titular_membership_id or "").strip():
            raise ValueError("COMPLEMENTARIO requiere titular_membership_id")
        if membership.titular_membership_id == membership.membership_id:
            raise ValueError("Una membresia no puede ser su propio titular")
        return
    raise ValueError("role no soportado")


def validate_single_active_assignment(assignments: list[CavaAssignment]) -> None:
    active_by_cava = {}
    for assignment in assignments:
        validate_cava_assignment(assignment)
        if assignment.status != CavaAssignmentStatus.ACTIVA:
            continue
        if assignment.cava_id in active_by_cava:
            raise ValueError("Una cava fisica no puede tener mas de una asignacion activa")
        active_by_cava[assignment.cava_id] = assignment.assignment_id
